#!/usr/bin/env python3
"""Direct finite-field enumeration of rings generated by pairs of idempotents."""
from itertools import product
from math import prod

CASES = [(2,1,(0,1)),(3,1,(0,1)),(5,1,(0,1)),
         (2,2,(1,1,1)),(2,3,(1,1,0,1)),(3,2,(1,0,1))]

def verify_field(p,e,modpoly, check_all=True):
    q=p**e
    digits=[tuple((x//p**i)%p for i in range(e)) for x in range(q)]
    def enc(ds): return sum((z%p)*p**i for i,z in enumerate(ds))
    add=[[enc([(digits[a][i]+digits[b][i])%p for i in range(e)]) for b in range(q)] for a in range(q)]
    mul=[]
    for a in range(q):
        row=[]
        for b in range(q):
            coeff=[0]*(2*e-1)
            for i,x in enumerate(digits[a]):
                for j,y in enumerate(digits[b]): coeff[i+j]=(coeff[i+j]+x*y)%p
            for k in range(2*e-2,e-1,-1):
                z=coeff[k]
                for i in range(e): coeff[k-e+i]=(coeff[k-e+i]-z*modpoly[i])%p
            row.append(enc(coeff[:e]))
        mul.append(row)
    mats=list(product(range(q),repeat=4))
    I=(1,0,0,1)
    def plus(A,B):return tuple(add[a][b] for a,b in zip(A,B))
    def times(A,B):
        a,b,c,d=A;w,x,y,z=B
        return (add[mul[a][w]][mul[b][y]],add[mul[a][x]][mul[b][z]],
                add[mul[c][w]][mul[d][y]],add[mul[c][x]][mul[d][z]])
    idemps=[A for A in mats if times(A,A)==A]
    assert len(idemps)==q*(q+1)+2,(q,len(idemps))
    rank1=[A for A in idemps if A not in ((0,0,0,0),I)]
    assert len(rank1)==q*(q+1)
    # Frobenius degree, independent of symbolic-polynomial factoring.
    def field_degree(a):
        z=a
        for d in range(1,e+1):
            z2=1
            for _ in range(p): z2=mul[z2][z]
            z=z2
            if z==a:return d
        raise RuntimeError('no Frobenius return')
    def span_dim(E,F):
        pivot={};basis=[];pending=[I,E,F]
        def coords(M):
            return [bit for entry in M for bit in digits[entry]]
        def insert(M):
            v=coords(M)
            for j in sorted(pivot):
                if v[j]:
                    fac=v[j]
                    v=[(x-fac*y)%p for x,y in zip(v,pivot[j])]
            if not any(v):return False
            j=next(i for i,x in enumerate(v) if x)
            inv=pow(v[j],-1,p)
            pivot[j]=[(x*inv)%p for x in v]
            basis.append(M)
            return True
        for M in pending:insert(M)
        n=0
        while n<len(basis):
            B=basis[n];n+=1
            for G in (E,F):insert(times(B,G))
        return len(basis)
    hist={};tested=0
    for E in rank1:
        for F in rank1:
            a=times(E,F);alpha=add[a[0]][a[3]]
            if alpha in (0,1):expect=None
            else:expect=4*field_degree(alpha)
            # F_q-algebra is full iff alpha is nondegenerate.
            if check_all or (tested<100 or (tested%311)==0):
                got=span_dim(E,F)
                if expect is None:
                    assert got<4*e,(p,e,E,F,alpha,got)
                else:
                    assert got==expect,(p,e,E,F,alpha,expect,got)
            hist[expect]=hist.get(expect,0)+1
            tested+=1
    order=q*(q+1)*(q-1)
    exp={}
    for a in range(q):
        if a in (0,1):continue
        dim=4*field_degree(a)
        exp[dim]=exp.get(dim,0)+order
    assert {k:v for k,v in hist.items() if k}==exp
    print('case',p,e,'q',q,'idempotents',len(idemps),
          'rank1 pairs',len(rank1)**2,'full pairs',hist.get(4*e,0),
          'nondegenerate subring spectrum',exp,'direct_checks',tested if check_all else 'sample')

if __name__=='__main__':
    for p,e,poly in CASES:
        verify_field(p,e,poly,check_all=True)
    print('VERIFY_OK')
